    if (pattern.size() != words.size()) return false;
    std::unordered_map<char, std::string> forward; std::unordered_map<std::string, char> backward;
    for (int i = 0; i < (int)words.size(); i++) { char c = pattern[i]; if (forward.count(c) && forward[c] != words[i]) return false;
        if (backward.count(words[i]) && backward[words[i]] != c) return false;
        forward[c] = words[i]; backward[words[i]] = c; } return true; }

std::vector<int> two_sum(const std::vector<int>& nums, int target) {
    std::unordered_map<int, int> seen;
    for (int i = 0; i < (int)nums.size(); i++) {
        int need = target - nums[i];
        if (seen.count(need)) return {seen[need], i};
        seen[nums[i]] = i;
    } return {}; }

func titleToNumber(columnTitle string) int {
	result := 0
	for _, c := range columnTitle {
		result = result*26 + int(c-'A'+1)
	}
	return result
}

class TreeNode:
    def __init__(self, val=0, left=None, right=None): self.val, self.left, self.right = val, left, right
def invert_tree(root):
    if root: root.left, root.right = invert_tree(root.right), invert_tree(root.left)
    return root

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} }; int height(TreeNode* node) { if (!node) return 0;
    int left = height(node->left);
    int right = height(node->right);
    if (left < 0 || right < 0 || std::abs(left - right) > 1) return -1;
    return 1 + std::max(left, right); } bool is_balanced(TreeNode* root) { return height(root) >= 0; }

public int[] productExceptSelf(int[] nums) { int n = nums.length;
    int[] res = new int[n];
    res[0] = 1;
    for (int i = 1; i < n; i++) { res[i] = res[i - 1] * nums[i - 1];
    } int right = 1;
    for (int i = n - 1; i >= 0; i--) { res[i] *= right;
        right *= nums[i]; } return res; }

