fn word_pattern(pattern: &str, s: &str) -> bool { use std::collections::HashMap;
    let words: Vec<&str> = s.split_whitespace().collect();
    let letters: Vec<char> = pattern.chars().collect();
    if letters.len() != words.len() { return false; } let mut forward = HashMap::new();
    let mut backward = HashMap::new();
    for (&c, word) in letters.iter().zip(words.iter()) { if forward.get(&c).map_or(false, |&v| v != *word) { return false; } if backward.get(*word).map_or(false, |&v| v != c) { return false; } forward.insert(c, *word);
        backward.insert(*word, c); } true }

def missing_number(nums):
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

function wordPattern(pattern, s) { const words = s.split(' ');
  if (pattern.length !== words.length) return false;
  const forward = new Map(); const backward = new Map();
  for (let i = 0; i < words.length; i++) { const a = pattern[i];
    const b = words[i]; if (forward.has(a) && forward.get(a) !== b) return false;
    if (backward.has(b) && backward.get(b) !== a) return false;
    forward.set(a, b); backward.set(b, a); } return true; }

void reverse_string(std::string& s) {
    int left = 0, right = (int)s.size() - 1;
    while (left < right) std::swap(s[left++], s[right--]);
}

bool is_happy(int n) { std::unordered_set<int> seen;
    while (n != 1 && seen.insert(n).second) { int total = 0;
        while (n > 0) { int digit = n % 10;
            total += digit * digit;
            n /= 10;
        } n = total;
    } return n == 1; }

def max_area(height):
    left, right, best = 0, len(height) - 1, 0
    while left < right:
        best = max(best, min(height[left], height[right]) * (right - left))
        left, right = (left + 1, right) if height[left] < height[right] else (left, right - 1)
    return best

struct TreeNode { int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
}; bool has_path_sum(TreeNode* root, int targetSum) { if (!root) return false;
    if (!root->left && !root->right) return root->val == targetSum;
    return has_path_sum(root->left, targetSum - root->val)
        || has_path_sum(root->right, targetSum - root->val); }

int missing_number(const std::vector<int>& nums) {
    int n = nums.size();
    int total = n * (n + 1) / 2;
    for (int num : nums) total -= num;
    return total;
}

function containsDuplicate(nums) {
  const seen = new Set();
  for (const n of nums) {
    if (seen.has(n)) return true;
    seen.add(n);
  } return false;
}

public int strStr(String haystack, String needle) {
    if (needle.isEmpty()) return 0;
    for (int i = 0; i <= haystack.length() - needle.length(); i++) {
        if (haystack.startsWith(needle, i)) return i;
    }
    return -1;
}

bool is_power_of_two(int n) {
