}

public int mySqrt(int x) { if (x < 2) return x;
    int lo = 1, hi = x / 2, answer = 0;
    while (lo <= hi) { int mid = lo + (hi - lo) / 2;
        if ((long) mid * mid <= x) { answer = mid;
            lo = mid + 1;
        } else { hi = mid - 1; } }
    return answer; }

def max_subarray(nums):
    best = cur = nums[0]
    for n in nums[1:]:
        cur = max(n, cur + n)
        best = max(best, cur)
    return best

function diameterOfBinaryTree(root) { let best = 0;
  const depth = (node) => { if (!node) return 0;
    const left = depth(node.left);
    const right = depth(node.right);
    best = Math.max(best, left + right);
    return 1 + Math.max(left, right); }; depth(root);
  return best; }

fn str_str(haystack: &str, needle: &str) -> i32 {
    if needle.is_empty() {
        return 0;
    } match haystack.find(needle) {
        Some(index) => index as i32,
        None => -1,
    } }

function moveZeroes(nums) {
  let write = 0;
  for (const n of nums) {
    if (n !== 0) nums[write++] = n;
  } while (write < nums.length) nums[write++] = 0;
  return nums;
}

fn merge_intervals(intervals: &mut Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    intervals.sort_by_key(|interval| interval[0]);
    let mut merged: Vec<Vec<i32>> = Vec::new();
    for interval in intervals.iter() { match merged.last_mut() {
            Some(last) if interval[0] <= last[1] => { last[1] = last[1].max(interval[1]);
            } _ => merged.push(interval.clone()), } }
    merged }

function isValid(s) { const stack = [];
  const pairs = { ')': '(', ']': '[', '}': '{' }; for (const c of s) {
    if (c === '(' || c === '[' || c === '{') { stack.push(c);
    } else if (stack.pop() !== pairs[c]) { return false;
    } }
  return stack.length === 0;
}

func sortedSquares(nums []int) []int { result := make([]int, len(nums))
	left, right := 0, len(nums)-1
	for i := len(nums) - 1; i >= 0; i-- {
		if abs(nums[left]) > abs(nums[right]) { result[i] = nums[left] * nums[left]
			left++ } else { result[i] = nums[right] * nums[right]
			right-- } }
	return result }

func binarySearch(arr []int, target int) int { lo, hi := 0, len(arr)-1
	for lo <= hi { mid := lo + (hi-lo)/2
		if arr[mid] == target { return mid
		} else if arr[mid] < target { lo = mid + 1
		} else { hi = mid - 1
		} }
	return -1 }

function plusOne(digits) {
  for (let i = digits.length - 1; i >= 0; i--) {
    if (digits[i] < 9) { digits[i]++;
      return digits;
    } digits[i] = 0;
  } return [1, ...digits];
}

function majorityElement(nums) { let count = 0;
  let candidate = 0;
  for (const n of nums) {
    if (count === 0) candidate = n;
    count += n === candidate ? 1 : -1;
  } return candidate;
}

def group_anagrams(strs):
    groups = {}
    for s in strs:
        key = ''.join(sorted(s))
        groups.setdefault(key, []).append(s)
    return list(groups.values())

def longest_common_prefix(strs):
    prefix = strs[0] if strs else ''
    for s in strs[1:]:
        while prefix and not s.startswith(prefix): prefix = prefix[:-1]
    return prefix

fn longest_common_prefix(strs: &[String]) -> String {
    if strs.is_empty() { return String::new();
    } let mut prefix = strs[0].clone();
    for s in &strs[1..] {
        while !s.starts_with(&prefix) { prefix.pop();
            if prefix.is_empty() { return prefix;
            } } } prefix }

def has_path_sum(root, target):
    if not root: return False
    if not root.left and not root.right: return root.val == target
    return has_path_sum(root.left, target - root.val) or has_path_sum(root.right, target - root.val)

