class ListNode { int val;
    ListNode next;
    ListNode(int val) { this.val = val; } } public ListNode reverseList(ListNode head) { ListNode prev = null;
    while (head != null) { ListNode next = head.next;
        head.next = prev;
        prev = head;
        head = next; } return prev; }

public void rotate(int[] nums, int k) { int n = nums.length;
    k %= n;
    reverse(nums, 0, n - 1);
    reverse(nums, 0, k - 1);
    reverse(nums, k, n - 1); } private void reverse(int[] nums, int left, int right) { while (left < right) { int temp = nums[left];
        nums[left++] = nums[right];
        nums[right--] = temp; } }

function mergeIntervals(intervals) { intervals.sort((a, b) => a[0] - b[0]);
  const merged = [];
  for (const [start, end] of intervals) {
    const last = merged[merged.length - 1];
    if (last && start <= last[1]) last[1] = Math.max(last[1], end);
    else merged.push([start, end]);
  } return merged; }

function hammingWeight(n) {
  let count = 0;
  while (n !== 0) {
    count += n & 1;
    n >>>= 1;
  } return count;
}

function invertTree(root) {
  if (!root) return null;
  [root.left, root.right] = [invertTree(root.right), invertTree(root.left)];
  return root;
}

def move_zeroes(nums):
    write = 0
    for n in nums:
        if n != 0: nums[write], write = n, write + 1
    for i in range(write, len(nums)): nums[i] = 0
    return nums

public int climbStairs(int n) { int a = 1, b = 1;
    for (int i = 0; i < n - 1; i++) {
        int temp = a + b;
        a = b;
        b = temp;
    } return b;
}
